import pathlib,json,statistics
b=pathlib.Path('output/render-performance-three-transfer');d=pathlib.Path('docs/performance/2026-10-25-three-transfer');d.mkdir(exist_ok=True)
def read(n):
 p=b/n/'report.json';return json.loads(p.read_text()) if p.exists() else {}
def val(r,key,stat='median'):return (r.get(key) or {}).get(stat)
def f(x):return '—' if x is None else f'{x:.2f}'
def work(r,key):return ((r.get('work') or {}).get('gltf',{}).get(key) or {}).get('perApplicationRaf')
lines=['# Přenos postupů z Three.js do Rust/WASM — 25.10.2026','','Změny: přímé složení transformační matice YXZ a využití již publikované matice objektu v glTF přípravě. Bez změny kvality, shaderu, geometrie, počtu objektů, simulace nebo XR prezentace. Další kroky Three.js nejsou automaticky pokládány za vhodné či ověřené.','','## Co jsme převzali a proč','','Lokální Three r170 `Matrix4.compose` zapisuje výslednou matici přímo; `Object3D.updateMatrixWorld` používá připravenou lokální matici. U nás se tvořilo/násobilo pět dílčích matic a glTF publikace navíc znovu počítala root, přestože už je uložen v `ObjectRenderData`. Přeneseny jsou tyto principy, nikoli Three renderer. Zachována naše Euler konvence T·Ry·Rx·Rz·S, obecné glTF normal matrices i existující invalidace.','','[Podrobný deník a zdrojový audit](../THREE_TRANSFER_2026-10-25.md). Archiv obsahuje přesný použitý Three r170 zdroj s MIT licencí. Příprava samostatných objektů, hledání instancovaných skupin, SDK přechody a materiály nejsou mezi oběma enginy totožné; nelze tím vysvětlit každou milisekundu rozdílu.','','## Identita a postup','','Vlastní větev `codex/wasm-render-performance`, základ `64bfda680`; navazuje na předchozí overlap optimalizaci. Baseline `6f9a3bba`, přímé skládání `6236f6b4`, kombinace s cache `292f27c1`. Úplné hashe a manifesty jsou v archivu. Desktop Apple M1/Chrome, headless ANGLE/Metal; fyzický Quest neověřený. Externí GPU aktivita ani teploty nejsou potvrzené. 960 × 640, DPR 1, AA vypnuté, seed 1337, stejné assety/kamera a elapsed-time pohyb.','','Hlavní test: 6144 viditelných objektů, 12288 trojúhelníků, 6 skutečných příkazů; 3 střídavé páry AB/BA/AB, 8s zahřátí a 25s měření, profiler prokazatelně vypnutý. Kalibrace proběhla jen na 6f9; shodné zátěže pro oba buildy. CPU je součet aplikačních RAF callbacků, nikoli jen čisté GPU/encoding. RAF kadence není compositor/input-to-display.','','[Skutečně spuštěné příkazy a stavy](commands.json) · [Předem zaznamenaný plán](plan.json) · [Ověření](validation.json) · [Hashy archivu](archive-manifest.json)','','## Hlavní párové měření','','| Backend/verze/pár | CPU medián/p95/p99 ms | RAF p95/p99 ms | RAF překročení počet / součet nad budget ms |','|---|---:|---:|---:|']
for backend in ['wg','gl']:
 if backend=='gl':lines+=['| Backend/verze/pár | CPU medián/p95/p99 ms | RAF p95/p99 ms | RAF překročení počet / součet nad budget ms |','|---|---:|---:|---:|']
 x=read('paired-'+backend)
 for r in x.get('results',[]):lines.append(f"| {backend} {r['label']} {r['pair']} | {f(val(r,'rafCallbackCpu'))}/{f(val(r,'rafCallbackCpu','p95'))}/{f(val(r,'rafCallbackCpu','p99'))} | {f(val(r,'rafInterval','p95'))}/{f(val(r,'rafInterval','p99'))} | {val(r,'rafInterval','overruns')}/{f(val(r,'rafInterval','overrunDurationMs'))} |")
 if x.get('comparisons'):
  c=x['comparisons'][0];ratio=c['cpuRatio']['median'];lines+=['',f"{backend}: medián párových poměrů CPU {ratio:.6f}, úspora {(1-ratio)*100:.2f}%; pixelové páry "+str([v['pixel']['exact'] for v in c['paired']])+f". [Data](paired-{backend}/summary.json).",'']
lines+=['','Změny ponecháváme pro doloženou úsporu přípravy: všechny tři WebGPU páry a dva ze tří WebGL párů mají nižší CPU medián. První WebGL pár se zhoršil o 0,1 ms. Špičky nejsou ve všech bězích lepší a RAF mediány zůstaly kolem 16,7 ms; nejde o obecné zrychlení FPS.','','Rozpočet 16,667 ms, tolerance 0,5 ms. Překročení je součet času nad budget u intervalů nad tolerancí; zaokrouhlení kolem16,67ms samo není regrese. Plné průměry/maxima, raw časování a cold-ready rozsah jsou v reportech. První direct-only pilot a malé kontroly jsou oddělené a nezakládají samostatné procento pro každou změnu.','','## Samostatný profil a prostředky','','Profil zapnutý, 2s/8s. CPU scopes jsou vzorky přibližně 10Hz, nikoli histogram každého snímku. Diagnostika API na samostatné stránce cold-init+1s. GPU WebGPU je pojmenovaný pass; GL je asynchronní RAF command interval, může zahrnovat CPU/driver mezery; není to celé GPU frame. Nesčítat CPU+GPU ani vnořené scopes.','','| Backend/verze | CPU ms | glTF update / scene.gpuUpdates ms | GPU scope ms | draw/instance/tris za RAF | upload calls / uniform+palette B za RAF | nové instance pages |','|---|---:|---:|---:|---:|---:|---:|']
for backend in ['wg','gl']:
 for label in ['before','after']:
  for r in read('profile-'+label+'-'+backend).get('results',[]):
   scopes=r.get('sampledCpuScopeMs') or {};gpu=(r.get('gpuPassMs') or {}).get('scene.main',{}).get('median') if backend=='wg' else val(r,'glRafGpuMs')
   lines.append(f"| {backend} {label} | {f(val(r,'rafCallbackCpu'))} | {f(scopes.get('gltf.update',{}).get('median'))}/{f(scopes.get('scene.gpuUpdates',{}).get('median'))} | {f(gpu)} | {f(work(r,'drawCalls'))}/{f(work(r,'instancesDrawn'))}/{f(work(r,'trianglesDrawn'))} | {f(work(r,'bufferUploadCalls'))}/{f(work(r,'uniformUploadBytes'))} | {f(((r.get('work') or {}).get('gltf',{}).get('instancePagesCreated') or {}).get('delta'))} |")
lines+=['','Upload bytes jsou glTF uniform+palette požadavky, nikoli všechny render uploady nebo fyzický sběrnicový provoz. Gauges retinované kapacity nejsou počty alokací. API příkazy/vytvoření/změny stavu jsou v `apiOperations` jednotlivých reportů; nejsou to warm allocation totals. GPU page churn se touto změnou neopravoval.','','## Přímé Three.js kontroly','','Oba backendové testy výše jsou náš renderer před/po. Následuje zvlášť náš WebGL2 vs lokální Three r170 WebGL2: 3 střídavé páry, 4s/10s, bez profileru. 6144 objektů/12288 trojúhelníků, shodná geometrie/grid/pohyb/rozlišení. Materiály,osvětlení,handedness a část přípravy se liší: pixel gate je vypnutý, žádná deklarovaná ekvivalence celé hry.','','| Three reprezentace | Rust CPU mediány párů ms | Three CPU mediány párů ms | Rust/Three medián párového poměru | skutečné commands Rust/Three |','|---|---:|---:|---:|---:|']
for kind in ['objects','instanced']:
 x=read('three-'+kind);rows=x.get('results',[])
 if not rows:continue
 a=sorted([r for r in rows if r['label']=='baseline'],key=lambda r:r['pair']);c=sorted([r for r in rows if r['label']=='candidate'],key=lambda r:r['pair']);ratios=[val(v,'rafCallbackCpu')/val(u,'rafCallbackCpu') for v,u in zip(a,c)]
 lines.append(f"| {kind} | "+'/'.join(f(val(r,'rafCallbackCpu')) for r in a)+' | '+'/'.join(f(val(r,'rafCallbackCpu')) for r in c)+f" | {f(statistics.median(ratios))}× | {f(work(a[-1],'drawCalls'))}/{f((c[-1].get('renderer') or {}).get('drawCalls'))} |")
lines+=['','Instanced Three má šest předem připravených skupin a vynechává naše dynamické hledání skupin. Objects varianta vytváří samostatné root/mesh dvojice a6144commands, Rust stále6. Tyto kontroly ukazují zbývající CPU rozdíl; neprokazují univerzální náskok ani nutnost opustit Rust/WASM. Three WebGPU a celý shodný gameplay se v této sérii neměřily.','','## Kontroly dynamiky a skutečných scén','','Jedna krátká 2s/8s dvojice na workload/backendu,profiler off. Malé rozdíly orientační,scény na60Hz neprokazují throughput.','','| Workload | CPU před/po ms | RAF p95/p99 po ms | pixelová kontrola / přesné |','|---|---:|---:|---:|']
for backend in ['wg','gl']:
 for family in ['dynamic','rim-static','arena-static']:
  x=read('paired-'+family+'-'+backend);rows=x.get('results',[])
  if len(rows)!=2:continue
  a,c=rows;pixel=x.get('comparisons',[{}])[0].get('paired',[{}])[0].get('pixel',{})
  lines.append(f"| {family}-{backend} | {f(val(a,'rafCallbackCpu'))}/{f(val(c,'rafCallbackCpu'))} | {f(val(c,'rafInterval','p95'))}/{f(val(c,'rafInterval','p99'))} | {'PASS' if pixel.get('pass') else 'FAIL'} / {pixel.get('exact')} |")
lines+=['','Řím WebGL2 prošel předem stanovenou pixelovou tolerancí, ale není bitově totožný: maximální rozdíl jednoho kanálu je1/255, žádný pixel nepřekračuje toleranci8. Z16 stejnorendererových párů je15 přesných; všech6 hlavních zátěžových párů je přesných. Golden images se neměnily.','','## Ověření a další krok','','- 15 unikátních cílených native testů, včetně 4096 numerických případů a aktuálnosti cache na skutečném Fox GLB.','- 14 maintained browser/backend případů na konečném 292f release PASS, včetně nezávislé unbatched pixel reference, mirrored/nonuniform/skin/culling/shadow a skutečných protilehlých půlek při řezu v simulovaném XR.','- Strict wasm32 Clippy PASS; independent Astra source audit bez scoped blockeru.','- Předešlé smoke a functional testy nejsou důkazem fyzického Quest výkonu. Nový push gate/commit/push/nasazení na 8443 se neprováděl.','- Další ověřitelné kandidáty: opakované přípravy matrix/inverse/determinant na primitiva stejného uzlu; oddělení pose změn od root/options změn; již doložený instance-page allocation churn. Využití root normal nebo obecná změna normál se v této iteraci nepřidávala. Změřit zvlášť se stejným protokolem a zachovat shear/singular fallback.']
(d/'REPORT.md').write_text('\n'.join(lines)+'\n');print(str(d/'REPORT.md'))
